// Read the per-PNR action selections back from the action table (nodes 12/25),
// resolve the row's Edvin bucket, then publish the Zendesk child/silent ticket and the
// Edvin errand entry the parent's node 32 loop and node 44 registration consume.
//
// ONE COMBINED PNR, NEVER GRANDCHILDREN (confirmed 2026-08-24 against this tree's own
// architecture, not just the test matrix): node 83 collapses every PNR the agent selected
// into a single combined-PNR record, and node 2 upserts that ONE record into
// transforms.customer_action_pnrs - there is no per-PNR loop on the VI path (see the
// claude.md node, "ONE COMBINED PNR, ONE ERRAND"), so this array is never longer than one
// row. Grandchild tickets only exist when 2+ DISTINCT (type+action) rows share one PROCEED
// bucket, which needs 2+ rows to begin with - impossible here. So this node always
// produces exactly ONE ticket (a Child Ticket when the resolved bucket is "proceed", a
// Silent Ticket otherwise) and NEVER a grandchild. The (type+action) grouping and
// grandchild-building code that used to live here has been removed as dead code. The
// PARENT tree's own node 27 still needs that logic - it handles real multi-PNR, multi-
// action selections - so do not port this simplification there.

let customer_action_pnrs = transforms.customer_action_pnrs || [];

// Reconstruct the EXACT select name node 12 rendered. Node 12 sanitizes the PNR
// (safePnr) before naming the field; read it back the same way so the lookup never
// misses and silently drops a proceed PNR into the "default" bucket.
function safePnr(pnr) {
  return String(pnr || "").replace(/[^a-zA-Z0-9_-]/g, "_");
}

// The table on node 12 renders action NAMES as its option values today; an earlier or
// later build may render action IDs. Resolve against actionId, then id, then name, so a
// value submitted by either render still finds its action - and with it, its BUCKET.
function findActionForSelection(item, selectedValue) {
  const wanted = String(selectedValue == null ? "" : selectedValue).trim();
  if (!wanted) return null;
  const actionsArray = Array.isArray(item.actions_array) ? item.actions_array : [];
  return actionsArray.find(action => action && (
    String(action.actionId) === wanted ||
    String(action.id) === wanted ||
    String(action.name).trim() === wanted
  )) || null;
}

// Node 85 (Select Passengers - VI) / node 86 (Continue) put `passengers` (the raw
// views.findorder rows) and `formatted_passengers` (the HTML for content-node display)
// onto transforms.current_pnr before node 2 ever runs, so every row here already carries
// both - they ride through the spread below unchanged. mergePassengers de-dupes by
// first+last name, matching the parent tree's own node 27 shape, so a VI child_ticket
// looks identical in structure to one the parent would have built itself.
function mergePassengers(items) {
  const unique = [];
  const seen = new Set();
  items.forEach(item => {
    (item.passengers || []).forEach(p => {
      const key = (p.passengerFirstName || "") + "|" + (p.passengerLastName || "");
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(p);
      }
    });
  });
  return unique;
}

let unresolved_selections = [];

let bucket_stitch = customer_action_pnrs.map((item, index) => {
  const variableName = `customer_action_${safePnr(item.pnr)}_${index}`;
  const rawSelection = ZT.getVariableValue(variableName, "");
  const selectedAction = findActionForSelection(item, rawSelection);

  ZT.log("node 27 | read " + variableName + " = " + JSON.stringify(rawSelection) +
         " -> action=" + JSON.stringify(selectedAction && selectedAction.name) +
         " | bucket=" + JSON.stringify(selectedAction && selectedAction.bucket));

  if (!selectedAction || !selectedAction.bucket) {
    unresolved_selections.push({
      pnr: item.pnr,
      type: item.type || "",
      field: variableName,
      raw: rawSelection,
      reason: !rawSelection ? "selection_unreadable"
            : !selectedAction ? "lookup_failed"
            : "bucket_missing"
    });
  }

  // drop actions_array from the stored record
  const { actions_array, ...rest } = item;

  return {
    ...rest,
    customer_action: (selectedAction && selectedAction.name) || rawSelection,
    actionId: selectedAction && selectedAction.actionId != null ? selectedAction.actionId : null,
    bucket: (selectedAction && selectedAction.bucket) || "",
    bucketId: selectedAction ? selectedAction.bucketId : null,
    edvin_actions: (selectedAction && selectedAction.edvin_actions) || {}
  };
});

// Diagnostics only on this tree: the parent tree's re-pick screen (its nodes 50/51) has no
// counterpart here yet, so an unresolved selection still falls through to a silent ticket.
// See the claude.md node, "Open items".
ZT.setFormData("has_unresolved_selections", unresolved_selections.length > 0);
ZT.setFormData("unresolved_selections_count", unresolved_selections.length);
ZT.setTransformData("unresolved_selections", unresolved_selections);
if (unresolved_selections.length) {
  ZT.log("node 27 | UNRESOLVED selections: " + JSON.stringify(unresolved_selections));
}

ZT.setTransformData("customer_action_pnrs", bucket_stitch);
ZT.log("bucket_stitch: " + JSON.stringify(bucket_stitch));

// ONE ROW IN, ONE TICKET OUT. No (type+action) grouping is needed to decide how many
// tickets exist, because there is only ever one row to look at - see the header note.
const isProceed = it => (it.bucket || "").trim().toLowerCase() === "proceed";

let child_tickets = [];
if (bucket_stitch.length) {
  const row = bucket_stitch[0];

  if (bucket_stitch.length > 1) {
    // Defensive only - should never happen on the VI path (see header note). Logged
    // instead of silently dropping every row after the first.
    ZT.log("node 27 | WARNING: " + bucket_stitch.length + " rows reached this VI node " +
           "(expected exactly 1 combined PNR) - using row 0 only, the rest are dropped.");
  }

  const proceed = isProceed(row);
  child_tickets.push({
    child_ticket: {
      title: (proceed ? "Child Ticket: " : "Silent Ticket: ") + row.pnr,
      pnr: row.pnr,
      bucket: row.bucket,
      bucketId: row.bucketId,
      category: row.category,
      customer_action: row.customer_action || "",
      type: row.type || "",
      passengers: mergePassengers([row]),
      formatted_passengers: row.formatted_passengers || "",
      grandchild_tickets: [] // VI never produces grandchildren - see header note
    }
  });
}

ZT.setTransformData("child_tickets", child_tickets);

// Edvin errand-registration list: the same one row. Built fresh each run (never
// appended) so a Back-nav re-entry cannot double the list.
let final_pnrs = bucket_stitch.length ? [bucket_stitch[0]] : [];
ZT.setTransformData("final_pnrs", final_pnrs);

ZT.setFormData("update_ticket_tag", "customer_action_table_completed");

//// Child Tickets Summary Note (Zendesk ticket update)
function buildChildTicketsNote(childTickets) {
  const isProceedTicket = ct => (ct.child_ticket.bucket || "").trim().toLowerCase() === "proceed";
  const childCount = childTickets.filter(isProceedTicket).length;
  const silentCount = childTickets.length - childCount;

  let note = `(Child Tickets: ${childCount}, Silent Tickets: ${silentCount})\n\n`;

  childTickets.forEach(ct => {
    const t = ct.child_ticket;
    const label = isProceedTicket(ct) ? "Child Ticket" : "Silent Ticket";

    note += `**${label}**: ${t.pnr},
  **Contact Reason**: ${t.category || ""},
  **Customer Action**: ${t.customer_action || ""},
  **Bucket**: ${t.bucket || ""}
`;

    if (t.passengers && t.passengers.length) {
      const names = t.passengers
        .map(p => [p.passengerFirstName, p.passengerLastName].filter(Boolean).join(" "))
        .filter(Boolean)
        .join(", ");
      if (names) note += `  **Passengers**: ${names}\n`;
    }

    note += `\n`;
  });

  return note.trim();
}

let child_tickets_note = buildChildTicketsNote(child_tickets);
ZT.setTransformData("child_tickets_note", child_tickets_note);
ZT.log("child_tickets_note: " + child_tickets_note);

