// NODE 82 - Partner / order-age route
//
// Picks which STG rule set the contact follows and hands node 49 a single scalar:
//   route = "50"  Booking, OR an ETG order created before the 21 May 2026 cutoff
//   route = "66"  everything else (ETG, on or after the cutoff)
//
// Two things this guards that the first version did not:
//
// 1. DATE-ONLY, TIMEZONE-FREE COMPARISON. `new Date('2026-05-21T00:00:00')` is parsed as
//    LOCAL midnight, while Edvin's orderCreated is an ISO timestamp (usually UTC). An
//    order created late on 20 May UTC could land either side of a local-midnight cutoff
//    depending on where the engine runs. Comparing the YYYY-MM-DD prefixes as strings is
//    exact and has no timezone in it at all.
//    BOUNDARY: an order created ON 2026-05-21 routes to node 66, unchanged from the
//    original `< 2026-05-21T00:00:00`. Node 50 is titled "prior 21May26" and node 66
//    "post 22may2026", so the 21st itself is not described by either title - confirm with
//    ETG which side owns it before this goes to more agents.
//
// 2. THE ORDER DATE HAS TWO SOURCES. Node 48 carries an `orderCreated` date field (the
//    manual/testing entry) and the Edvin order lookup carries the real value. The agent's
//    entry wins when present, then the API, and if neither is readable the route falls
//    back to "66" (the current rules) and says so in the log - instead of `new Date(undefined)`
//    silently comparing false.

function datePart(value) {
  if (!value) return "";
  const s = String(value).trim();
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + "-" + m[2] + "-" + m[3];
  // Fall back to a real parse for formats like "05/21/2026" that the agent field may post.
  const d = new Date(s);
  if (isNaN(d.getTime())) return "";
  const pad = n => (n < 10 ? "0" + n : String(n));
  return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
}

const CUTOFF = "2026-05-21";

const partner = ZT.getVariableValue("zd_brand_name", "");
const agentEnteredDate = ZT.getVariableValue("orderCreated", "");
const apiDate = (actions.findorder && actions.findorder.orderCreated) || "";
const order_created = datePart(agentEnteredDate) || datePart(apiDate);

let route = "66";
if (partner == "Booking" || (order_created && order_created < CUTOFF)) {
  route = "50";
}

ZT.setFormData("route", route);
ZT.setFormData("order_created_date", order_created);

ZT.log("node 82 | partner=" + JSON.stringify(partner) +
       " | orderCreated(agent)=" + JSON.stringify(agentEnteredDate) +
       " | orderCreated(api)=" + JSON.stringify(apiDate) +
       " | resolved=" + JSON.stringify(order_created) +
       " | cutoff=" + CUTOFF +
       " | route=" + route +
       (order_created ? "" : " | WARNING no readable order date - routed by partner only"));

83.content:
// NODE 83 - Set VI Combined PNR (ROOT of this tree)
//
// VI = Virtual Interlining / Self Transfer Guarantee. In this use case the whole
// self-transfer itinerary is handled as ONE errand, so the PNRs the agent selected on
// the order grid in the parent tree (node 6 -> views.findorder -> transforms.selected_pnrs)
// are collapsed here into a single "combined PNR" record. Every VI screen, the action
// card (node 12/25), the child ticket and the Edvin errand then speak about that one
// record instead of a per-PNR loop.
//
// Runs once per VI case, before node 48, and is the only place VI state is reset.
//
// Writes:
//   transforms.current_pnr          the combined record (what all VI content nodes read)
//   transforms.combined_pnr_record  the same record, kept unmodified as the baseline
//   transforms.combined_pnr         the joined PNR string
//   transforms.pnr_banner           the header line the VI screens print
//   combined_pnr / combined_pnr_count (form data, so logic nodes + COs can read them)
//
// Reads transforms.selected_pnrs, which the PARENT tree's node 24 sets from views.findorder
// before it opens this subtree. VI never re-does the order lookup or the PNR selection.
//
// Also clears the VI selection variables and the per-run accumulators: form data never
// expires, so without this a second contact in the same session inherits the previous
// one's disruption / STG answers.

const VI_SELECTION_VARS = [
  "partner",
  "orderCreated",
  "route",
  "disruption_type",
  "delay_reason",
  "flight_affected",
  "stg_alternatives_sameday_sc",
  "stg_alternatives_overnight_sc",
  "stg_alternatives_sameday_td",
  "stg_alternatives_overnight_td",
  "stg_refund"
];

VI_SELECTION_VARS.forEach(name => ZT.setFormData(name, ""));

ZT.setTransformData("customer_action_pnrs", []);
ZT.setTransformData("final_pnrs", []);
ZT.setTransformData("child_tickets", []);
ZT.setTransformData("final_pnrs_count", 0);
ZT.setFormData("child_tickets_count", 0);
ZT.setFormData("grandchild_tickets_count", 0);

function uniqList(values) {
  return [...new Set(values.filter(Boolean).map(v => String(v)))];
}

// The grid rows the agent picked. Each row is {pnr, postSaleHandleType, providerSystem, id}
// (plus passenger fields when the order lookup returned them on the same record).
let selected_pnrs = transforms.selected_pnrs || [];
if (!selected_pnrs.length) {
  selected_pnrs = views.findorder || [];
}

const pnr_list = uniqList(selected_pnrs.map(p => p.pnr));
const combined_pnr = pnr_list.join(", ");
let provider_booking_id = selected_pnrs[0].id.toString();
ZT.setFormData("provider_booking_id", provider_booking_id)

// Field names follow the v5 hand-off contract (VI node 118) so the two designs stay
// interchangeable: pnr joined, postSaleHandleType joined with " / ", id kept as the flat
// array of provider booking ids, providerPnrIds alongside it for the Edvin payload.
const provider_ids = uniqList(selected_pnrs.map(p => p.id));

const combined_pnr_record = {
  pnr: combined_pnr,
  pnrs: pnr_list,
  pnr_count: pnr_list.length,
  vi_pnr_count: pnr_list.length,
  is_combined_pnr: true,
  postSaleHandleType: uniqList(selected_pnrs.map(p => p.postSaleHandleType)).join(" / "),
  providerSystem: uniqList(selected_pnrs.map(p => p.providerSystem)).join(" / "),
  id: provider_ids,
  providerPnrIds: provider_ids,
//   passengers: selected_passengers,
//   formatted_passengers: formatPassengers(selected_passengers)
};

// The parent tree's node 11 gate reads transforms.isMorePNR: false means "the per-PNR
// loop is done". Set here (and left false) so the VI record can never be routed into a
// per-PNR loop, whichever node the parent returns through.
ZT.setTransformData("isMorePNR", false);
ZT.setTransformData("pnr_index", 0);

ZT.setTransformData("current_pnr", combined_pnr_record);
ZT.setTransformData("combined_pnr_record", combined_pnr_record);
ZT.setTransformData("combined_pnr", combined_pnr);
ZT.setFormData("combined_pnr", combined_pnr);
ZT.setFormData("combined_pnr_count", pnr_list.length);
ZT.setTransformData(
  "pnr_banner",
  `<h3>Combined PNR: ${combined_pnr || "(no PNR selected)"}</h3>`
);

ZT.log("node 80 | combined_pnr=" + JSON.stringify(combined_pnr) +
       " | pnr_count=" + pnr_list.length);

84.content:
// NODE 84 - Set VI Finals (combined PNR)
//
// Hand-off to the parent "Register Errands - Dynamic" tree, which resumes at its node 3
// (any child tickets?) and then runs the child-ticket loop, the internal note and the
// Edvin registration loop. The parent consumes exactly two things from here:
//
//   transforms.final_pnrs   node 44's cursor - ONE Edvin errand per entry
//   transforms.current_pnr  the record nodes 44/43 and the content nodes read
//
// On the VI path the whole self-transfer itinerary is ONE errand, so both hold the SAME
// single combined-PNR record: final_pnrs = [combined], current_pnr = combined.
// The scalars are mirrored as form data so logic nodes and Connected Objects can address
// the selected action and its bucket by name - that is what was previously being lost
// between this subtree and the parent workflow.
//
// `passengers` (raw array, from node 85/86) and `formatted_passengers` (HTML) both ride
// through unchanged via the `...combined` spread below - node 27 guarantees `combined`
// (== stitched[0]) already carries them, so the parent's node 21 (internal note,
// record.passengers) and node 44 (Edvin errand free text, passengerLines(rec)) see the
// same passenger data the agent picked on node 85 with no extra wiring needed here.

let stitched = transforms.customer_action_pnrs || [];

function uniqList(values) {
  return [...new Set(values.filter(Boolean).map(v => String(v)))];
}

function firstNonEmpty(sources) {
  for (let i = 0; i < sources.length; i++) {
    const v = sources[i];
    const list = Array.isArray(v) ? v : (v === undefined || v === null || v === "" ? [] : [v]);
    const cleaned = uniqList(list);
    if (cleaned.length) return cleaned;
  }
  return [];
}

let combined = stitched[0] || transforms.combined_pnr_record || transforms.current_pnr || {};

// Defensive: the VI path is meant to produce exactly one row. If more than one exists
// (an older session's rows, or a future per-PNR variant of this tree), fold them into the
// one combined record rather than registering several errands for one itinerary.
if (stitched.length > 1) {
  const pnrs = uniqList(stitched.map(r => r.pnr));

  // Same de-dupe-by-name shape as node 27's mergePassengers, so a folded record's
  // passenger list looks the same as the normal one-row path's.
  const passengerKey = p => (p.passengerFirstName || "") + "|" + (p.passengerLastName || "");
  const seenPassengers = new Set();
  const mergedPassengers = [];
  stitched.forEach(r => (r.passengers || []).forEach(p => {
    const key = passengerKey(p);
    if (!seenPassengers.has(key)) {
      seenPassengers.add(key);
      mergedPassengers.push(p);
    }
  }));

  combined = {
    ...combined,
    pnr: pnrs.join(", "),
    pnrs: pnrs,
    pnr_count: pnrs.length,
    vi_pnr_count: pnrs.length,
    passengers: mergedPassengers,
    formatted_passengers: stitched.map(r => r.formatted_passengers || "").join("")
  };
  ZT.log("node 84 | folded " + stitched.length + " rows into one combined PNR: " + combined.pnr);
}

// The joined PNR string node 83 built is the source of truth for the combined PNR - keep
// it even if the stitched row lost it somewhere upstream.
const baseline = transforms.combined_pnr_record || {};
const combined_pnr = combined.pnr || transforms.combined_pnr || baseline.pnr || "";

// Provider booking ids stay a FLAT, de-duped array here. The parent tree's node 27 builds
// providerBookingIds as JSON.stringify(group.map(i => i.id)); on a collapsed record `id` is
// already an array, so that path would nest. Build it flat, once, from the FIRST source
// that has anything (the sources all hold the same ids - concatenating them triples the
// list), and let the Edvin payload (CO #184) read providerBookingIds / providerPnrIds here.
const provider_ids = firstNonEmpty([
  combined.providerPnrIds,
  combined.id,
  baseline.providerPnrIds,
  baseline.id
]);

// The VI / STG answers, flattened onto the record as well as kept in vi_details, so both
// the parent's note (node 21) and anything reading the record by field name can see them.
const g = name => ZT.getVariableValue(name, "");

// The STG ladder is walked top-down and each rung the agent could not fill answers
// "None of the above is available", so the OUTCOME is the LAST rung that named a real
// offer - not the first answer found. If every rung was declined, the outcome genuinely is
// "None of the above is available".
const NO_OFFER = "None of the above is available";
const STG_LADDER = [
  "stg_alternatives_sameday_sc",
  "stg_alternatives_overnight_sc",
  "stg_alternatives_sameday_td",
  "stg_alternatives_overnight_td",
  "stg_refund"
];
const stg_answers = STG_LADDER.map(g).filter(Boolean);
const stg_offers = stg_answers.filter(v => v !== NO_OFFER);
const stg_outcome = stg_offers.length
  ? stg_offers[stg_offers.length - 1]
  : (stg_answers.length ? NO_OFFER : "");

const final_record = {
  ...combined,
  pnr: combined_pnr,
  is_combined_pnr: true,
  providerPnrIds: provider_ids,
  providerBookingIds: JSON.stringify(provider_ids),
  partner: g("partner"),
  disruption_type: g("disruption_type"),
  delay_reason: g("delay_reason"),
  flight_affected: g("flight_affected"),
  stg_outcome: stg_outcome,
  stg_trail: stg_answers.join(" -> "),
  vi_details: combined.vi_details || transforms.vi_details || {},
  vi_details_text: combined.vi_details_text || transforms.vi_details_text || ""
};

// FINAL VARIABLES the larger dynamic-errands workflow handles.
ZT.setTransformData("final_pnrs", [final_record]);
ZT.setTransformData("current_pnr", final_record);
ZT.setTransformData("customer_action_pnrs", [final_record]);
ZT.setTransformData("final_pnrs_count", 0);
ZT.setTransformData("isMorePNR", false);

// Scalars for logic nodes / Connected Objects. `type` is deliberately NOT overwritten -
// it holds the Edvin type ID that node 1's select and node 2's lookup depend on.
ZT.setFormData("combined_pnr", combined_pnr);
ZT.setFormData("customer_action", final_record.customer_action || "");
ZT.setFormData("customer_action_id", final_record.actionId == null ? "" : final_record.actionId);
ZT.setFormData("bucket", final_record.bucket || "");
ZT.setFormData("bucket_id", final_record.bucketId == null ? "" : final_record.bucketId);
ZT.setFormData("errand_type", final_record.type || "");
ZT.setFormData("stg_outcome", stg_outcome);
ZT.setFormData("stg_trail", stg_answers.join(" -> "));

ZT.log("node 84 | FINALS | pnr=" + JSON.stringify(final_record.pnr) +
       " | type=" + JSON.stringify(final_record.type) +
       " | customer_action=" + JSON.stringify(final_record.customer_action) +
       " | bucket=" + JSON.stringify(final_record.bucket) +
       " | bucket_id=" + JSON.stringify(final_record.bucketId) +
       " | providerPnrIds=" + JSON.stringify(provider_ids) +
       " | final_pnrs=1");

86.content:
// NODE 86 - Continue (attach the node 85 passenger selection to the combined PNR record)
//
// BUGFIX 2026-08-24 (root cause of the "undefined" child/silent ticket titles): this used
// to read the existing record with ZT.getVariableValue("combined_pnr_record"). That reads
// the FORM-DATA (default) namespace - it is not where ZT.setTransformData("combined_pnr_record", ...)
// (node 83) actually put it. Per the Zingtree namespace rules, a transforms-namespace object
// is read back as `transforms.<name>`, never via ZT.getVariableValue (that's for form-data
// scalars / query params only, and always needs an explicit default - see the claude.md
// node, "PASSENGERS ARE CAPTURED ONCE..."). Reading it the wrong way found nothing, so
// combined_pnr_record silently became "" here, and `{...combined_pnr_record, passengers,
// formatted_passengers}` collapsed to just `{passengers, formatted_passengers}` - wiping out
// `pnr` and every other field node 83 built. That record was then written straight back
// into transforms.current_pnr / combined_pnr_record, so `pnr` stayed undefined for the rest
// of the tree - which is exactly why node 27's tickets were titled "Child Ticket: undefined"
// / "Silent Ticket: undefined" (row.pnr was undefined by the time node 27 built the title).
//
// The parent tree's own node 9 ("Format Passengers") does this correctly already - it reads
// `transforms.current_pnr` directly. This node now matches that pattern.

let combined_pnr_record = transforms.combined_pnr_record || transforms.current_pnr || {};
let selected_passengers = views.findorder || [];
ZT.setFormData("has_passenger_selection", selected_passengers.length >= 1);

function formatPassengers(passengers) {
    return passengers
        .map(p => {
            const first = p.passengerFirstName ? `<div><strong>First Name:</strong> ${p.passengerFirstName}</div>` : "";
            const last = p.passengerLastName ? `<div><strong>Last Name:</strong> ${p.passengerLastName}</div>` : "";
            return first + last;
        })
        .filter(Boolean)
        .join('<hr style="margin: 8px 0;">');
}

combined_pnr_record = {
    ...combined_pnr_record,
    passengers: selected_passengers,
    formatted_passengers: formatPassengers(selected_passengers)
};

ZT.setTransformData("current_pnr", combined_pnr_record);
ZT.setTransformData("combined_pnr_record", combined_pnr_record);
